
INSERT INTO public.checkup_sections (key, title, subtitle, body, sort_order, is_active) VALUES
('hero','Чекапы','Комплексные программы для ранней диагностики и контроля здоровья. Выберите подходящий чекап и пройдите обследование за один визит.',NULL,1,true),
('flagship','Флагманские чекапы','Готовые программы обследования со скидкой по сравнению с отдельными исследованиями.',NULL,2,true),
('how','Как проходит чекап','Четыре простых шага — от записи до консультации с врачом.','1. Записываетесь по телефону или онлайн.
2. Приходите натощак в удобный филиал.
3. Сдаёте анализы и проходите исследования за один визит.
4. Получаете результаты и разбор с врачом.',3,true),
('who','Кому подойдёт чекап','Профилактическое обследование рекомендовано всем взрослым раз в год.','— Если давно не проверяли здоровье;
— При хронической усталости, лишнем весе, повышенном давлении;
— При наследственных рисках (диабет, онкология, болезни сердца);
— Перед началом занятий спортом или планированием беременности.',4,true),
('faq','Частые вопросы','Коротко о главном.','Нужно ли готовиться? Анализы сдаются натощак, за 8–12 часов до визита не есть.
Сколько занимает по времени? Большинство программ проходят за 1,5–3 часа.
Когда будут результаты? Базовые анализы — в день обращения, расширенные — до 2 суток.
Можно ли пройти чекап ребёнку? Да, есть отдельная детская программа.',5,true);

INSERT INTO public.checkup_cards (slug, title, subtitle, badge, price, body, sort_order, is_active) VALUES
('muzhskoy-chekap','Мужской чекап','Комплексная проверка сердца, гормонов и мужского здоровья','Популярное','от 4 900 сом','Что входит: общий и биохимический анализ крови, липидный профиль, глюкоза, ПСА (онкомаркер простаты), тестостерон, УЗИ органов брюшной полости и почек, ЭКГ, консультация терапевта и уролога.',1,true),
('zhenskiy-chekap','Женский чекап','Гормоны, гинекология и профилактика онкологии','Популярное','от 5 400 сом','Что входит: общий и биохимический анализ крови, гормоны щитовидной железы, УЗИ малого таза и молочных желёз, мазок на онкоцитологию, ЭКГ, консультация терапевта и гинеколога.',2,true),
('detskiy-chekap','Детский чекап','Профилактический осмотр ребёнка перед садиком и школой',NULL,'от 3 200 сом','Что входит: общий анализ крови и мочи, анализ на паразитов, УЗИ брюшной полости, ЭКГ, консультация педиатра и осмотр узких специалистов.',3,true),
('chekap-diabet','Чекап «Диабет под контролем»','Ранняя диагностика и контроль сахарного диабета',NULL,'от 3 900 сом','Что входит: глюкоза натощак, гликированный гемоглобин HbA1c, инсулин, липидный профиль, креатинин и мочевина, анализ мочи на микроальбумин, консультация эндокринолога.',4,true),
('chekap-serdce','Чекап «Здоровое сердце»','Оценка рисков инфаркта и гипертонии',NULL,'от 4 500 сом','Что входит: ЭКГ, ЭхоКГ (УЗИ сердца), липидный профиль, коагулограмма, электролиты, измерение давления в динамике, консультация кардиолога.',5,true),
('chekap-bazovyy','Базовый чекап','Быстрая проверка основных показателей здоровья','За 1 визит','от 2 400 сом','Что входит: общий анализ крови, общий анализ мочи, глюкоза, печёночные и почечные пробы, ЭКГ, консультация терапевта.',6,true);
